To setup add this to your .bashrc/.zshrc function dbt_run_changed() { children=$1 models=$(git diff --name-only | grep '\.sql$' | awk -F '/' '{ print $NF }' | sed "s/\.sql$/${children}/g" | tr '\n' ' ') echo "Running models: ${models}" dbt run --models $models
}
### Run only the locally staged(into version control) dbt models
``````bash
dbt_run_staged_changed () { children=$1 models=$(git diff --name-only --cached | grep '\.sql$' | awk -F '/' '{ print $NF }' | sed "s/\.sql$/${children}/g" | tr '\n' ' ') echo "Running models: ${models}" dbt run --models $models
}
